//! battmem.resource's functions: a few hundred bits of settings kept where
//! no file has to be read to get them - memory that a reset leaves alone,
//! where the chip has some, and plain memory where it has none. A
//! resource: no Open or Close, its first function in the first slot. The
//! base comes from OpenResource("battmem.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/battmem_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const battmem = @import("../resources/battmem.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "battmem.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const ObtainBattSemaphore = libraries.lvo(0);
    pub const ReleaseBattSemaphore = libraries.lvo(1);
    pub const ReadBattMem = libraries.lvo(2);
    pub const WriteBattMem = libraries.lvo(3);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const ObtainBattSemaphore = *const fn (*BattMemBase) callconv(.c) void;
    pub const ReleaseBattSemaphore = *const fn (*BattMemBase) callconv(.c) void;
    pub const ReadBattMem = *const fn (*BattMemBase, [*]u8, u32, u32) callconv(.c) u32;
    pub const WriteBattMem = *const fn (*BattMemBase, [*]const u8, u32, u32) callconv(.c) u32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const BattMemBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *BattMemBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The bits to this task alone, for a read and the write that depends on
    /// it; held again by the same task, it is released as often.
    pub fn ObtainBattSemaphore(self: *BattMemBase) void {
        return libraries.call(self, LVO.ObtainBattSemaphore, Fn.ObtainBattSemaphore, .{});
    }

    /// Give the bits back.
    pub fn ReleaseBattSemaphore(self: *BattMemBase) void {
        return libraries.call(self, LVO.ReleaseBattSemaphore, Fn.ReleaseBattSemaphore, .{});
    }

    /// `length` bits from bit `offset` into `buffer`, from its first byte's
    /// bit 0 up; 0, or BATTMEMERR_RANGE when they run past the end.
    pub fn ReadBattMem(self: *BattMemBase, buffer: [*]u8, offset: u32, length: u32) u32 {
        return libraries.call(self, LVO.ReadBattMem, Fn.ReadBattMem, .{ buffer, offset, length });
    }

    /// `length` bits from `buffer` to bit `offset` on; 0, or BATTMEMERR_RANGE
    /// when they run past the end.
    pub fn WriteBattMem(self: *BattMemBase, buffer: [*]const u8, offset: u32, length: u32) u32 {
        return libraries.call(self, LVO.WriteBattMem, Fn.WriteBattMem, .{ buffer, offset, length });
    }
};
